"""Editor script: create the Remastered-look materials in /Game/Remastered (no game data; regenerated by this script).

Lit counterparts of the Classic world materials (Scripts/make_world_materials.py, never touched here): they take the
same parameters (BaseTex, Lightmap, UVScrollU/V, MPC_SSXWorld) so the game copies a Classic instance's values onto a
Remastered one (World/SSXRemasterWorld.cpp), plus RmNormal / RmMasks from tools/make_remaster_maps.py. The original
baked light (terrain lightmap, prop vertex colours) stays in as a tint of the albedo and as ambient occlusion, weighted
by MPC_SSXRemaster.BakedWeight, and as the ambient light (emissive albedo x baked x BakedAmbient, which Lumen also
bounces), so each track keeps its painted mood and shadows never go black.
PP_RmScene replaces the tonemapper in the Remastered look: unlit pixels (riders, sky, particles: still the Classic
materials, PS2 display values) pass through exactly as PP_SSXAuthoredColour shows them; lit pixels (linear light) get
the exposure, a soft shoulder and the sRGB encode.
"""
import os
import struct
import zlib

import unreal

PATH = "/Game/Remastered"
WORLD = "/Game/World"
assets = unreal.EditorAssetLibrary
mel = unreal.MaterialEditingLibrary
tools = unreal.AssetToolsHelpers.get_asset_tools()

ENC = "(lerp(1.055 * pow(max({x}, 0.0), 1.0 / 2.4) - 0.055, {x} * 12.92, step({x}, 0.0031308)))"
DEC = "(lerp(pow((max({x}, 0.0) + 0.055) / 1.055, 2.4), {x} / 12.92, step({x}, 0.04045)))"

# Classic terrain: c = (t - LM.rgb) * LM.a * 2 in display space (Mode 0). Baked = c / (2 t): the share of the full
# texture brightness the original's lightmap lets through, as linear light.
TERRAIN_BAKED = f"""
float3 t = {ENC.format(x='Tex')};
float3 c = saturate((t - LM.rgb) * LM.a * (255.0 / 128.0));
float3 r = saturate(c / max(t * (255.0 / 128.0), 1.0 / 255.0));
return {DEC.format(x='r')};
"""
# Classic props: c = t * VC * 2 in display space.
PROP_BAKED = f"""
float3 r = saturate(VC.rgb * (255.0 / 128.0));
return {DEC.format(x='r')};
"""
# PS2 textures: 0x80 is full brightness.
ALBEDO = f"""
float3 t = saturate({ENC.format(x='Tex')} * (255.0 / 128.0));
float3 a = {DEC.format(x='t')} * AlbedoScale;
return a * lerp(float3(1.0, 1.0, 1.0), Baked, BakedWeight);
"""
AMBIENT = f"""
float3 t = saturate({ENC.format(x='Tex')} * (255.0 / 128.0));
return {DEC.format(x='t')} * AlbedoScale * Baked * BakedAmbient;
"""
AO = "return lerp(1.0, dot(Baked, float3(0.299, 0.587, 0.114)), BakedWeight) * M.a;"
ROUGH = "return clamp(BaseRough + (M.r - 0.5) - M.g * 0.25, 0.05, 1.0);"
SPEC = "return 0.35 + M.g * 0.3;"
LIGHTMAP_UV = """
float2 l = Local;
if (SwapUV > 0.5) l = l.yx;
if (FlipU > 0.5) l.x = 1.0 - l.x;
if (FlipV > 0.5) l.y = 1.0 - l.y;
float2 texel = clamp(l * 8.0, 0.5, 7.5);
return Origin + texel / 8.0 * float2(1.0 / 128.0, 1.0 / 64.0);
"""
# FUN_00200390
PROP_GS_ALPHA = """float at = min(floor((floor(A * 255.0 + 0.001) + 1.0) * 0.5), 128.0);
float av = floor(VA * 255.0 + 0.5);
return min(floor(at * av / 128.0), 255.0);
"""
PROP_ATEST = "return As > 1.0 ? 1.0 : 0.0;"
PROP_CORE = "return As >= 128.0 ? 1.0 : 0.0;"
DRAW_CLIP = "return (Depth <= DrawDistance ? 1.0 : 0.0) * Alpha;"
PP_SCENE = f"""
float3 s = max(Scene.rgb / View.PreExposure, 0.0);
if (SM.r < 0.001) return saturate(s * Brightness);
float3 c = s * Exposure;
c = max(lerp(dot(c, float3(0.2126, 0.7152, 0.0722)).xxx, c, Saturation), 0.0);
float k = 0.8;
c = c < k ? c : k + (1.0 - k) * (1.0 - exp(-(c - k) / (1.0 - k)));
return saturate({ENC.format(x='c')} * Brightness);
"""

F1, F2, F3 = (unreal.CustomMaterialOutputType.CMOT_FLOAT1, unreal.CustomMaterialOutputType.CMOT_FLOAT2,
              unreal.CustomMaterialOutputType.CMOT_FLOAT3)


def connect(src, out, dst, inp):
    if not mel.connect_material_expressions(src, out, dst, inp):
        raise RuntimeError(f"cannot connect {src.get_name()}.{out} -> {dst.get_name()}.{inp}")


def connect_prop(src, out, prop):
    if not mel.connect_material_property(src, out, prop):
        raise RuntimeError(f"cannot connect {src.get_name()}.{out} -> {prop}")


def recreate(name, cls, factory):
    full = f"{PATH}/{name}"
    if assets.does_asset_exist(full):
        assets.delete_asset(full)
    return tools.create_asset(name, PATH, cls, factory)


def expr(mat, cls, x, y, **props):
    e = mel.create_material_expression(mat, cls, x, y)
    for k, v in props.items():
        e.set_editor_property(k, v)
    return e


def custom(mat, x, y, code, out_type, inputs, desc):
    e = expr(mat, unreal.MaterialExpressionCustom, x, y)
    e.set_editor_property("code", code)
    e.set_editor_property("output_type", out_type)
    e.set_editor_property("description", desc)
    ins = []
    for n, _ in inputs:
        ci = unreal.CustomInput()
        ci.set_editor_property("input_name", n)
        ins.append(ci)
    e.set_editor_property("inputs", ins)
    for n, (src, out) in inputs:
        connect(src, out, e, n)
    return e


def coll(mat, mpc, name, x, y):
    return expr(mat, unreal.MaterialExpressionCollectionParameter, x, y, collection=mpc, parameter_name=name)


def _png(path, w, h, rgba):
    """Write a tiny uniform RGBA PNG (the editor's Python has no PIL)."""
    raw = b"".join(b"\0" + bytes(rgba) * w for _ in range(h))

    def chunk(tag, data):
        return struct.pack(">I", len(data)) + tag + data + struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF)
    with open(path, "wb") as f:
        f.write(bytes([0x89]) + b"PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", w, h, 8, 6, 0, 0, 0))
                + chunk(b"IDAT", zlib.compress(raw)) + chunk(b"IEND", b""))


def neutral_masks():
    """Default for RmMasks: roughness offset 0 (0x80), no sparkle, no emissive, open (A 1)."""
    name = "T_RmMasksNeutral"
    if not assets.does_asset_exist(f"{PATH}/{name}"):
        stage = unreal.Paths.convert_relative_path_to_full(unreal.Paths.project_intermediate_dir())
        png = os.path.join(stage, f"{name}.png")
        _png(png, 4, 4, (128, 0, 0, 255))
        task = unreal.AssetImportTask()
        for k, v in (("filename", png), ("destination_path", PATH), ("destination_name", name),
                     ("automated", True), ("replace_existing", True), ("save", False)):
            task.set_editor_property(k, v)
        unreal.SystemLibrary.execute_console_command(None, "Interchange.FeatureFlags.Import.PNG 0")
        tools.import_asset_tasks([task])
        unreal.SystemLibrary.execute_console_command(None, "Interchange.FeatureFlags.Import.PNG 1")
        os.remove(png)
    tex = unreal.load_asset(f"{PATH}/{name}")
    tex.set_editor_property("srgb", False)
    tex.set_editor_property("compression_settings", unreal.TextureCompressionSettings.TC_MASKS)
    tex.set_editor_property("mip_gen_settings", unreal.TextureMipGenSettings.TMGS_NO_MIPMAPS)
    assets.save_asset(f"{PATH}/{name}", only_if_is_dirty=False)
    return tex


def tex_param(mat, name, x, y, kind="color"):
    e = expr(mat, unreal.MaterialExpressionTextureSampleParameter2D, x, y, parameter_name=name)
    if kind == "normal":
        e.set_editor_property("texture", unreal.load_asset("/Engine/EngineMaterials/FlatNormal"))
        e.set_editor_property("sampler_type", unreal.MaterialSamplerType.SAMPLERTYPE_NORMAL)
    elif kind == "masks":
        e.set_editor_property("texture", neutral_masks())
        e.set_editor_property("sampler_type", unreal.MaterialSamplerType.SAMPLERTYPE_MASKS)
    elif kind == "lightmap":
        e.set_editor_property("texture", unreal.load_asset(f"{WORLD}/T_SSXLightmapNeutral"))
        e.set_editor_property("sampler_type", unreal.MaterialSamplerType.SAMPLERTYPE_LINEAR_COLOR)
    else:
        e.set_editor_property("texture", unreal.load_asset("/Engine/EngineResources/WhiteSquareTexture"))
        e.set_editor_property("sampler_type", unreal.MaterialSamplerType.SAMPLERTYPE_COLOR)
    return e


def finish(m):
    mel.recompile_material(m)
    assets.save_asset(m.get_path_name().split(".")[0], only_if_is_dirty=False)
    unreal.log(f"[ssx] created {m.get_path_name()}")


def lit_material(name, blend):
    m = recreate(name, unreal.Material, unreal.MaterialFactoryNew())
    m.set_editor_property("shading_model", unreal.MaterialShadingModel.MSM_DEFAULT_LIT)
    m.set_editor_property("blend_mode", blend)
    m.set_editor_property("two_sided", True)
    m.set_editor_property("opacity_mask_clip_value", 0.5)
    return m


def surface(m, rm, base, baked, uv=None):
    """Base colour, normal, roughness, specular and AO of a lit world material from the texture sample and the
    original's baked light (linear float3)."""
    normal = tex_param(m, "RmNormal", -1000, 300, "normal")
    masks = tex_param(m, "RmMasks", -1000, 550, "masks")
    if uv is not None:
        connect(uv, "", normal, "UVs")
        connect(uv, "", masks, "UVs")
    albedo = custom(m, -400, -200, ALBEDO, F3,
                    [("Tex", (base, "RGB")), ("Baked", (baked, "")),
                     ("AlbedoScale", (coll(m, rm, "AlbedoScale", -700, -350), "")),
                     ("BakedWeight", (coll(m, rm, "BakedWeight", -700, -280), ""))], "RmAlbedo")
    connect_prop(albedo, "", unreal.MaterialProperty.MP_BASE_COLOR)
    amb = custom(m, -400, -50, AMBIENT, F3,
                 [("Tex", (base, "RGB")), ("Baked", (baked, "")),
                  ("AlbedoScale", (coll(m, rm, "AlbedoScale", -700, -120), "")),
                  ("BakedAmbient", (coll(m, rm, "BakedAmbient", -700, -50), ""))], "RmBakedAmbient")
    connect_prop(amb, "", unreal.MaterialProperty.MP_EMISSIVE_COLOR)
    connect_prop(normal, "RGB", unreal.MaterialProperty.MP_NORMAL)
    masks4 = expr(m, unreal.MaterialExpressionAppendVector, -700, 600)
    connect(masks, "RGB", masks4, "A")
    connect(masks, "A", masks4, "B")
    rough = custom(m, -400, 100, ROUGH, F1,
                   [("M", (masks4, "")), ("BaseRough", (coll(m, rm, "BaseRoughness", -700, 100), ""))], "RmRoughness")
    connect_prop(rough, "", unreal.MaterialProperty.MP_ROUGHNESS)
    connect_prop(custom(m, -400, 200, SPEC, F1, [("M", (masks4, ""))], "RmSpecular"), "", unreal.MaterialProperty.MP_SPECULAR)
    ao = custom(m, -400, 300, AO, F1,
                [("Baked", (baked, "")), ("M", (masks4, "")),
                 ("BakedWeight", (coll(m, rm, "BakedWeight", -700, 400), ""))], "RmAO")
    connect_prop(ao, "", unreal.MaterialProperty.MP_AMBIENT_OCCLUSION)


def clip(m, mpc, alpha):
    depth = expr(m, unreal.MaterialExpressionPixelDepth, -700, 800)
    c = custom(m, -300, 850, DRAW_CLIP, F1,
               [("Depth", (depth, "")), ("DrawDistance", (coll(m, mpc, "DrawDistance", -700, 900), "")), ("Alpha", alpha)],
               "DrawClip")
    connect_prop(c, "", unreal.MaterialProperty.MP_OPACITY_MASK)


unreal.AssetRegistryHelpers.get_asset_registry().scan_paths_synchronous([PATH, WORLD], True)
mpc = unreal.load_asset(f"{WORLD}/MPC_SSXWorld")
if mpc is None:
    raise RuntimeError("MPC_SSXWorld missing: run make_world_materials.py first")

# Updated in place: a recreated collection gets new parameter GUIDs and breaks the materials that read it.
if assets.does_asset_exist(f"{PATH}/MPC_SSXRemaster"):
    rm = assets.load_asset(f"{PATH}/MPC_SSXRemaster")
else:
    rm = tools.create_asset("MPC_SSXRemaster", PATH, unreal.MaterialParameterCollection,
                            unreal.MaterialParameterCollectionFactoryNew())
old = {str(p.get_editor_property("parameter_name")): p for p in rm.get_editor_property("scalar_parameters")}
scalars = []
for n, v in (("BakedWeight", 0.6), ("BakedAmbient", 0.55), ("AlbedoScale", 0.9), ("BaseRoughness", 0.8),
             ("Exposure", 1.0), ("Saturation", 1.15)):
    p = old.get(n) or unreal.CollectionScalarParameter()
    p.set_editor_property("parameter_name", n)
    p.set_editor_property("default_value", v)
    scalars.append(p)
rm.set_editor_property("scalar_parameters", scalars)
assets.save_asset(f"{PATH}/MPC_SSXRemaster", only_if_is_dirty=False)

for name, masked, clipped in (("M_RmTerrain", False, True), ("M_RmTerrain_Masked", True, True),
                              ("M_RmTerrainOpaque", False, False)):
    m = lit_material(name, unreal.BlendMode.BLEND_MASKED if clipped else unreal.BlendMode.BLEND_OPAQUE)
    base = tex_param(m, "BaseTex", -1100, -200)
    uv1 = expr(m, unreal.MaterialExpressionTextureCoordinate, -1700, 100, coordinate_index=1)
    uv2 = expr(m, unreal.MaterialExpressionTextureCoordinate, -1700, 200, coordinate_index=2)
    lmuv = custom(m, -1450, 150, LIGHTMAP_UV, F2,
                  [("Local", (uv1, "")), ("Origin", (uv2, "")),
                   ("SwapUV", (coll(m, mpc, "LightmapSwapUV", -1700, 300), "")),
                   ("FlipU", (coll(m, mpc, "LightmapFlipU", -1700, 380), "")),
                   ("FlipV", (coll(m, mpc, "LightmapFlipV", -1700, 460), ""))], "LightmapUV")
    lm = tex_param(m, "Lightmap", -1200, 150, "lightmap")
    connect(lmuv, "", lm, "UVs")
    lm4 = expr(m, unreal.MaterialExpressionAppendVector, -950, 150)
    connect(lm, "RGB", lm4, "A")
    connect(lm, "A", lm4, "B")
    baked = custom(m, -700, 0, TERRAIN_BAKED, F3, [("Tex", (base, "RGB")), ("LM", (lm4, ""))], "RmTerrainBaked")
    surface(m, rm, base, baked)
    if clipped:
        one = expr(m, unreal.MaterialExpressionConstant, -700, 1000, r=1.0)
        clip(m, mpc, (base, "A") if masked else (one, ""))
    finish(m)

for name, mode in (("M_RmProp", "plain"), ("M_RmProp_Masked", "atest"), ("M_RmPropOpaque", "opaque"),
                   ("M_RmProp_Core", "core")):
    m = lit_material(name, unreal.BlendMode.BLEND_OPAQUE if mode == "opaque" else unreal.BlendMode.BLEND_MASKED)
    base = tex_param(m, "BaseTex", -1100, -200)
    uv0 = expr(m, unreal.MaterialExpressionTextureCoordinate, -1700, -200, coordinate_index=0)
    su = expr(m, unreal.MaterialExpressionScalarParameter, -1700, -100, parameter_name="UVScrollU", default_value=0.0)
    sv = expr(m, unreal.MaterialExpressionScalarParameter, -1700, 0, parameter_name="UVScrollV", default_value=0.0)
    suv = expr(m, unreal.MaterialExpressionAppendVector, -1500, -50)
    connect(su, "", suv, "A")
    connect(sv, "", suv, "B")
    uvs = expr(m, unreal.MaterialExpressionAdd, -1300, -150)
    connect(uv0, "", uvs, "A")
    connect(suv, "", uvs, "B")
    connect(uvs, "", base, "UVs")
    vc = expr(m, unreal.MaterialExpressionVertexColor, -1000, 100)
    baked = custom(m, -700, 0, PROP_BAKED, F3, [("VC", (vc, ""))], "RmPropBaked")
    surface(m, rm, base, baked, uvs)
    if mode in ("atest", "core"):
        gs_a = custom(m, -1000, 800, PROP_GS_ALPHA, F1, [("A", (base, "A")), ("VA", (vc, "A"))], "PropGsAlpha")
        alpha = custom(m, -800, 800, PROP_ATEST if mode == "atest" else PROP_CORE, F1, [("As", (gs_a, ""))], "PropAlpha")
        clip(m, mpc, (alpha, ""))
    elif mode == "plain":
        clip(m, mpc, (expr(m, unreal.MaterialExpressionConstant, -700, 1000, r=1.0), ""))
    finish(m)

pp = recreate("PP_RmScene", unreal.Material, unreal.MaterialFactoryNew())
pp.set_editor_property("material_domain", unreal.MaterialDomain.MD_POST_PROCESS)
pp.set_editor_property("blendable_location", unreal.BlendableLocation.BL_REPLACING_TONEMAPPER)
scene = expr(pp, unreal.MaterialExpressionSceneTexture, -700, 0, scene_texture_id=unreal.SceneTextureId.PPI_POST_PROCESS_INPUT0)
sm = expr(pp, unreal.MaterialExpressionSceneTexture, -700, 200, scene_texture_id=unreal.SceneTextureId.PPI_SHADING_MODEL_ID)
enc = custom(pp, -350, 0, PP_SCENE, F3,
             [("Scene", (scene, "Color")), ("SM", (sm, "Color")),
              ("Brightness", (coll(pp, mpc, "Brightness", -700, 400), "")),
              ("Exposure", (coll(pp, rm, "Exposure", -700, 500), "")),
              ("Saturation", (coll(pp, rm, "Saturation", -700, 600), ""))], "RmScene")
connect_prop(enc, "", unreal.MaterialProperty.MP_EMISSIVE_COLOR)
finish(pp)
